Here is a minimal Terraform snippet to add SSE-KMS encryption to the bucket:

```
resource "aws_s3_bucket_server_side_encryption_configuration" "cardholder" {
  bucket = aws_s3_bucket.cg-cardholder-data-bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cardholder_key.arn
    }
    bucket_key_enabled = true
  }
}
```
